      longitudinal.detail.weight_type.lmm_glmm = row("No analysis weights are applied. LMM / GLMM weighted likelihood is not recommended as a routine default in this module because its interpretation depends strongly on the sampling design, target estimand, and software-specific likelihood definition. Use GEE for weighted marginal longitudinal inference, or report LMM / GLMM weights only as a separate design-justified sensitivity analysis outside the primary model.", h("")),
      longitudinal.detail.weight_type.none = row("No analysis weights are applied. This is the default for LMM / GLMM unless the study design requires sampling or longitudinal weights.", h("ebb684ec849d20eab080eca491ecb998eba5bc20eca081ec9aa9ed9598eca78020ec958aec8ab5eb8b88eb8ba42e20ec97b0eab5acec84a4eab384ec838120ed919cebb3b82feca285eb8ba820eab080eca491ecb998eab08020ed9584ec9a94ed9598eca78020ec958aec9cbceba9b420eab8b0ebb3b820ec84a0ed839dec9e85eb8b88eb8ba42e")),
      longitudinal.detail.weight_type.sampling = row("Uses the selected variable as a baseline sampling/design weight. Use this when the data were sampled with unequal probabilities or require survey/design weighting.", h("")),
      longitudinal.detail.weight_type.longitudinal = row("Uses the selected variable as a time-varying longitudinal analysis weight. This is usually the primary weighted option for GEE when weights vary by visit or person-period.", h("")),
      longitudinal.detail.weight_type.combined = row("Multiplies the selected analysis weight by generated inverse-probability weights for missingness/dropout sensitivity. Use this when both sampling/design weights and observation-process weights are needed.", h("")),
      longitudinal.detail.weight_type.default = row("No analysis weights are applied.", h("eab080eca491ecb998eba5bc20eca081ec9aa9ed9598eca78020ec958aec8ab5eb8b88eb8ba42e")),
      longitudinal.detail.weight_trim.p01_99 = row("Winsorizes extreme final weights below the 1st percentile and above the 99th percentile. This is a mild stability option for occasional extreme weights.", h("")),
      longitudinal.detail.weight_trim.p05_95 = row("Winsorizes final weights below the 5th percentile and above the 95th percentile. This is stronger and should be reported as a sensitivity choice because it can change the target weighted estimand.", h("")),
      longitudinal.detail.weight_trim.none = row("No trimming is applied. Use this when weights are stable or when preserving the original design weights is more important than variance stabilization.", h("")),
      longitudinal.detail.missing_strategy.available_lmm_glmm = row("Fits the unbalanced LMM / GLMM likelihood using observed repeated-measure records with complete selected model variables. A subject is not removed only because an outcome is missing at another visit, but rows with missing outcome, covariates, ID, or time for the fitted model are not imputed. This is appropriate as the primary mixed-model analysis when the MAR assumption is defensible; add MI or IPW sensitivity when covariate missingness or dropout mechanisms are important.", h("")),
      longitudinal.detail.missing_strategy.available_gee = row("Plain GEE is not likelihood-based. Available model rows can be fitted, but MAR dropout should be supported with MI, IPW, or WGEE sensitivity analysis.", h("")),
      longitudinal.detail.missing_strategy.available_other = row("Uses rows with observed selected model variables. Report whether the panel is balanced, and add MI or weighting sensitivity when missingness may depend on observed history.", h("")),
      longitudinal.detail.missing_strategy.subject_complete = row("Keeps only subjects / clusters with complete records on selected analysis variables. This is conservative and easy to report, but can reduce power and introduce bias when dropout is related to observed outcomes or covariates.", h("")),
      longitudinal.detail.missing_strategy.mi = row("MI: standard mice-based missing-data sensitivity analysis. It imputes incomplete selected model variables, including the dependent variable when missing, fits the selected model in each imputed dataset, and pools estimates using Rubin's rules; it is not a dedicated multilevel MI engine and should usually be reported as sensitivity for LMM / GLMM.", h("")),
