      data_editor.missing_choose_source = row("Choose detected rows, manual codes, or both.", h("eab090eca78020ed96892c20ec8898eb8f9920ecbd94eb939c20eb9890eb8a9420eb919820eb8ba420ec84a0ed839ded9598ec84b8ec9a942e")),
      data_editor.missing_no_candidates = row("No missing-value candidates are available.", h("ec82acec9aa920eab080eb8aa5ed959c20eab2b0ecb8a1eab09220ed9b84ebb3b4eab08020ec9786ec8ab5eb8b88eb8ba42e")),
      data_editor.missing_select_candidate = row("Select at least one candidate row to apply.", h("eca081ec9aa9ed95a020ed9b84ebb3b420ed9689ec9d8420ed9598eb829820ec9db4ec838120ec84a0ed839ded9598ec84b8ec9a942e")),
      data_editor.missing_select_detected_or_manual = row("Select detected rows or enter manual missing-value codes.", h("eab090eca78020ed9689ec9d8420ec84a0ed839ded9598eab1b0eb829820ec8898eb8f9920eab2b0ecb8a1eab09220ecbd94eb939ceba5bc20ec9e85eba0a5ed9598ec84b8ec9a942e")),
      data_editor.missing_user_rules_unavailable = row("User-missing rules are not available in this session.", h("ec9db420ec84b8ec8598ec9790ec849ceb8a9420ec82acec9aa9ec9e9020eab2b0ecb8a120eab79cecb999ec9d8420ec82acec9aa9ed95a020ec889820ec9786ec8ab5eb8b88eb8ba42e")),
      data_editor.missing_marked_user = row("Marked %s missing-value rule(s) as user missing for analysis. Original data values are preserved: %s", h("ebb684ec849dec9aa920ec82acec9aa9ec9e9020eab2b0ecb8a1eab092ec9cbceba19c202573eab09c20eab79cecb999ec9d8420ed919cec8b9ced9688ec8ab5eb8b88eb8ba42e20ec9b90ebb3b820eb8db0ec9db4ed84b020eab092ec9d8020ec9ca0eca780eb90a9eb8b88eb8ba43a202573")),
      data_editor.missing_no_values_changed = row("No values were changed.", h("ebb380eab2bdeb909c20eab092ec9db420ec9786ec8ab5eb8b88eb8ba42e")),
      data_editor.missing_converted = row("Converted %s value(s) to NA across %s variable(s): %s", h("2573eab09c20eab092ec9d84202573eab09c20ebb380ec8898ec9790ec849c204e41eba19c20ebb380ed9998ed9688ec8ab5eb8b88eb8ba43a202573"))
    )
    overlays <- if (exists("statedu_locale_overlays", mode = "function")) statedu_locale_overlays() else list()
    for (language in names(overlays)) {
      translations <- overlays[[language]]
      if (!is.list(translations) || length(translations) == 0) next
      for (key in names(translations)) {
        value <- translations[[key]]
        if (is.null(value) || length(value) == 0) next
        current <- cache[[key]]
        if (is.null(current) && grepl("^language[.][A-Za-z0-9_-]+$", key)) {
          code <- sub("^language[.]", "", key)
          spec <- statedu_language_registry()[[code]]
          if (!is.null(spec)) {
            current <- vapply(statedu_supported_languages(), function(target_language) {
              names <- spec$names %||% list(en = code)
              as.character(names[[target_language]] %||% names[["en"]] %||% code)
            }, character(1))
          }
        }
        current <- current %||% c(en = NA_character_, ko = NA_character_)
        current[[language]] <- as.character(value[[1]])
        cache[[key]] <- current
      }
    }
    cache <<- cache
    cache
  }
})

statedu_translation_row <- function(key) {
  row <- statedu_translation_table()[[key]]
  if (is.null(row)) {
    return(NULL)
  }
  languages <- statedu_supported_languages()
  values <- vapply(languages, function(language) {
    value <- if (language %in% names(row)) {
      row[[language]]
    } else if ("en" %in% names(row)) {
      row[["en"]]
    } else {
      key
    }
    if (is.null(value) || length(value) == 0 || is.na(value[[1]]) || !nzchar(as.character(value[[1]]))) {
      value <- if ("en" %in% names(row) && !is.na(row[["en"]]) && nzchar(as.character(row[["en"]]))) row[["en"]] else key
    }
    as.character(value)
  }, character(1))
  as.list(values)
}

statedu_translate <- function(key, language = statedu_initial_language(), fallback = NULL) {
  language <- normalize_app_language(language)
  row <- statedu_translation_table()[[key]]
  if (is.null(row)) {
    return(fallback %||% as.character(key))
  }
  value <- if (language %in% names(row)) {
    row[[language]]
  } else if ("en" %in% names(row)) {
    row[["en"]]
  } else if (!is.null(fallback)) {
    fallback
  } else {
    key
  }
  if (is.null(value) || length(value) == 0 || is.na(value[[1]]) || !nzchar(as.character(value[[1]]))) {
    value <- if ("en" %in% names(row) && !is.na(row[["en"]]) && nzchar(as.character(row[["en"]]))) {
      row[["en"]]
    } else if (!is.null(fallback)) {
      fallback
    } else {
      key
    }
  }
  as.character(value)
}

statedu_language_choices <- function(language = statedu_initial_language()) {
  languages <- statedu_supported_languages()
  labels <- vapply(languages, function(code) {
    statedu_translate(paste0("language.", code), language, statedu_language_display_name(code, language))
  }, character(1))
  stats::setNames(languages, labels)
}

statedu_ko <- function(key) {
  statedu_translate(key, "ko", key)
}
